/**
 * Guard: nothing under src/ may import from /reference.
 *
 * The design sheets are art direction, not assets. If they ever get imported
 * they would be bundled and shipped, which breaks the project's core rule that
 * every pixel is generated by our own code.
 */
import { readdir, readFile } from 'node:fs/promises';
import path from 'node:path';

const offenders = [];
async function walk(dir) {
  for (const e of await readdir(dir, { withFileTypes: true })) {
    const p = path.join(dir, e.name);
    if (e.isDirectory()) await walk(p);
    else if (/\.(ts|tsx|js|mjs|glsl|frag|vert)$/.test(e.name)) {
      const src = await readFile(p, 'utf8');
      if (/['"`][^'"`]*\breference\//.test(src)) offenders.push(p);
    }
  }
}
await walk('src');
if (offenders.length) {
  console.error('Reference images must never be imported by src/:');
  for (const o of offenders) console.error('  ' + o);
  process.exit(1);
}
console.log('ok: no reference imports in src/');
